import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { AlertCard, ModuleHeader, KpiCardSkeleton } from './talkxShared';
import { TalkXQueryBoundary } from './kit/states';
import { useTalkXSettings, useTalkXSettingUpdate } from '@/hooks/integrations/useTalkXSettings';
import { Settings, Save, RotateCcw } from 'lucide-react';

function displayValue(v: unknown): string {
  if (typeof v === 'object' && v !== null) return JSON.stringify(v);
  return String(v ?? '');
}

const BOOL_KEYS = new Set(['ai_insights']);

export function TalkXSettings() {
  const { data: settings, isLoading, error, refetch } = useTalkXSettings();
  const update = useTalkXSettingUpdate();
  const [edits, setEdits] = useState<Record<string, string>>({});
  const [saved, setSaved] = useState<string | null>(null);

  // X047: erro e vazio deixam de ser decididos a mao aqui. O boundary decide na ordem
  // carregando -> erro -> vazio -> conteudo, e o erro tem precedencia sobre o vazio.
  if (isLoading || error || !settings) {
    return (
      <TalkXQueryBoundary
        query={{ isLoading, isError: !!error, error: (error as Error) ?? null }}
        entity="as configurações"
        onRetry={() => refetch()}
        skeleton={<div className="space-y-3"><KpiCardSkeleton /><KpiCardSkeleton /></div>}
        isEmpty={false}
        empty={<></>}
      >
        <></>
      </TalkXQueryBoundary>
    );
  }

  function handleSave(key: string) {
    const raw = edits[key];
    if (raw === undefined) return;
    update.mutate(
      { key, raw },
      {
        onSuccess: () => {
          setSaved(key);
          setTimeout(() => setSaved(null), 2000);
          setEdits((prev) => { const n = { ...prev }; delete n[key]; return n; });
        },
      }
    );
  }

  return (
    <div className="space-y-6 max-w-2xl">
      <ModuleHeader
        icon={Settings}
        title="Configurações Talk X"
        subtitle="Parâmetros globais do módulo de campanhas"
      />

      <div className="divide-y rounded-lg border">
        {settings.map((row) => {
          const currentRaw = edits[row.key] ?? displayValue(row.value);
          const isBool = BOOL_KEYS.has(row.key);
          const boolVal = row.value === true || row.value === 'true';
          const isDirty = edits[row.key] !== undefined;
          // TL-175D (t_eedf548a): o rotulo da linha passa a NOMEAR o controle. O Switch
          // e um `<button role="switch">` sem nome e os campos sao `<input>` sem `<label for>`
          // — o axe reprovava `button-name` e `label` (criticos) nos dois temas. O id sai da
          // chave da configuracao (unica na lista), com o resto do nome normalizado.
          const labelId = `talkx-config-${row.key.replace(/[^a-zA-Z0-9_-]/g, '-')}`;
          const descId = row.description ? `${labelId}-desc` : undefined;

          return (
            <div key={row.key} className="flex items-start gap-4 px-4 py-3">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <code id={labelId} className="text-xs font-mono text-foreground">{row.key}</code>
                  {saved === row.key && (
                    <span className="text-3xs text-emerald-600 font-medium">Salvo!</span>
                  )}
                </div>
                {row.description && (
                  <p id={descId} className="text-xs text-muted-foreground mt-0.5">{row.description}</p>
                )}
              </div>

              {isBool ? (
                <div className="flex items-center gap-2 pt-0.5">
                  <Switch
                    aria-labelledby={labelId}
                    aria-describedby={descId}
                    checked={boolVal}
                    onCheckedChange={(v) => update.mutate({ key: row.key, raw: String(v) })}
                  />
                  <Label className="text-xs">{boolVal ? 'Ativo' : 'Inativo'}</Label>
                </div>
              ) : (
                <div className="flex items-center gap-2">
                  <Input
                    aria-labelledby={labelId}
                    aria-describedby={descId}
                    value={currentRaw}
                    onChange={(e) => setEdits((prev) => ({ ...prev, [row.key]: e.target.value }))}
                    className="h-7 text-xs font-mono w-48"
                  />
                  {isDirty && (
                    <>
                      <Button
                        size="icon" variant="ghost" className="h-7 w-7"
                        aria-label="Descartar alteração"
                        onClick={() => setEdits((prev) => { const n = { ...prev }; delete n[row.key]; return n; })}
                      >
                        <RotateCcw className="w-3 h-3" />
                      </Button>
                      <Button
                        size="icon" variant="default" className="h-7 w-7"
                        aria-label="Salvar"
                        disabled={update.isPending}
                        onClick={() => handleSave(row.key)}
                      >
                        <Save className="w-3 h-3" />
                      </Button>
                    </>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}
